package com.shanjay.mart.controller;
import com.shanjay.mart.dao.UserDAO;import com.shanjay.mart.service.AuthService;import com.shanjay.mart.model.User;import javax.servlet.*;import javax.servlet.http.*;import java.io.IOException;
public class LoginServlet extends HttpServlet {private AuthService auth;public void init(){auth=new AuthService(new UserDAO((javax.sql.DataSource)getServletContext().getAttribute("ds")));}protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.getRequestDispatcher("/WEB-INF/views/login.jsp").forward(r,s);}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{User u=auth.login(r.getParameter("email"),r.getParameter("password"));if(u==null){r.setAttribute("error","Invalid email or password.");doGet(r,s);return;}HttpSession old=r.getSession(false);if(old!=null)old.invalidate();HttpSession session=r.getSession(true);session.setMaxInactiveInterval(30*60);session.setAttribute("user",u);s.sendRedirect(r.getContextPath()+"/dashboard");}catch(Exception e){throw new ServletException(e);}}}
